const productCategoryNames = {MCB:'小型断路器',RCCB:'剩余电流动作断路器',RCBO:'带过流保护的剩余电流断路器',MCCB:'塑壳断路器',ACB:'万能式断路器',SPD:'浪涌保护器','AC contactor':'交流接触器','AC contactor auxiliary contacts':'接触器辅助触头','Thermal Overload Relay':'热过载继电器','Motor Protection Relay':'电动机保护器','Load Disconnector':'负荷隔离开关','Knife Blade Switch':'刀开关','Fuse Switch-Disconnector':'熔断器式隔离开关','Isolator switch':'隔离开关','Current transformer':'电流互感器','MCCB with residual current protection':'剩余电流塑壳断路器','HRC fuse link':'高分断熔断体','Fuse base':'熔断器底座','PV cylindrical fuse link':'光伏圆筒熔断体','PV fuse switch disconnector':'光伏熔断器式隔离开关'};
