const productSearchText = p => [p.model,p.name,p.name_en,p.supplier,p.category,productFamily(p),p.source,...Object.values(p.specs||{})].filter(Boolean).join(' ').toLowerCase();
function productMatchesFilters(p,search=true){return (!state.productFamily||productFamily(p)===state.productFamily)&&(!state.productCategory||p.category===state.productCategory)&&(!state.productPrice||(state.productPrice==='missing'?(p.purchase_price===''||p.purchase_price==null):(p.purchase_price!==''&&p.purchase_price!=null)))&&(!state.productKind||(state.productKind==='series'?productIsSeries(p):!productIsSeries(p)))&&(!search||productSearchText(p).includes(state.productSearch.toLowerCase().trim()));}
const activeSelectedProducts = i => (i.selected_product_ids||[]).filter(id=>product(id).id&&!product(id).archived);
