async function api(path,options={}) {
  const {body,method='GET'}=options;
  const headers={'X-Local-Request':'1'};
  if(body!==undefined && !(body instanceof FormData)) headers['Content-Type']='application/json';
  let res;
  try {res=await fetch(apiUrl(path),{method,headers,body:body===undefined?undefined:body instanceof FormData?body:JSON.stringify(body)});} catch (_) {throw new Error('无法连接本地服务。请确认应用仍在运行；当前输入已保留。');}
  let data;
  try {data=await res.json();} catch (_) {throw new Error('服务返回了无法读取的结果，请重试。当前资料不会被覆盖。');}
  if(!res.ok) throw new Error(data.error || '请求未成功，请检查输入后重试。');
  return data;
}
async function refresh(){state.data=await api('/api/state');updateChrome();}
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className='show'+(error?' error':'');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.className='',error?7000:4000);}
function showError(error,form){const box=form?.querySelector('.error-box')||$('#modal[open] .error-box');if(box){box.textContent=error.message;box.scrollIntoView({block:'nearest',behavior:'smooth'});}else toast(error.message,true);}
async function work(button,job){state.pending=(state.pending||0)+1;$('#workspace').disabled=true;const old=button?.innerHTML;if(button){button.disabled=true;button.textContent='正在处理…';}try{await job();}catch(error){showError(error,button?.closest('form'));}finally{state.pending--;$('#workspace').disabled=state.pending>0;if(button?.isConnected){button.disabled=false;button.innerHTML=old;}}}
function modal(title,sub,body,wide=false){const d=$('#modal');d.classList.toggle('wide',wide);$('#modal-content').innerHTML=`<div class="modal-head"><div><h2>${e(title)}</h2><p>${e(sub)}</p></div><button type="button" data-action="close-modal" class="close-button" aria-label="关闭窗口">×</button></div><div class="modal-body">${body}</div>`;if(!d.open)d.showModal();}
function closeModal(){$('#modal').close();}
