async function route(){
  const [view,id]=(location.hash.replace(/^#/,'')||'dashboard').split('/');state.view=['dashboard','products','inquiries','quotes','research','buyer-pages','settings'].includes(view)?view:'dashboard';
  if(state.view==='inquiries'&&id)state.inquiryId=Number(id);if(state.view==='quotes'&&id)state.quoteId=Number(id);
  if(!state.data)return;updateChrome();render();
  if(state.view==='inquiries'&&state.inquiryId){await loadMatches(state.inquiryId);if(state.view==='inquiries'&&state.tab==='matching')render();}
}
function navigate(view,id){const hash=`#${view}${id?'/'+id:''}`;if(location.hash===hash)route();else location.hash=hash;}
function render(){if(!state.data)return;if(window.V2?.isView(state.view)){$('#main').innerHTML=window.V2.render(state.view);return;}const renderers={dashboard:renderDashboard,products:renderProducts,inquiries:renderInquiries,quotes:renderQuotes,settings:renderSettings};$('#main').innerHTML=renderers[state.view]();}
function latestQuote(inquiryId){return state.data.quotes.filter(q=>q.inquiry_id===inquiryId).reduce((latest,q)=>!latest||Number(q.version)>Number(latest.version)||(Number(q.version)===Number(latest.version)&&q.id>latest.id)?q:latest,null);}
function nextAction(i){
  if(!i.analysis)return ['整理询盘需求','先提取原文中已说明的信息，列出缺失项。','analysis'];
  if(!i.analysis_reviewed)return ['审核需求与候选产品','核对原文依据，处理参数冲突与待确认项。','matching'];
  if(!i.selected_product_ids?.length)return ['补充需求并确认选型','当前尚未确认可报价产品。','matching'];
  const latest=latestQuote(i.id);
  if(!latest)return ['创建英文报价','填写价格、交期与条款，保存待审核草稿。','quote'];
  if(latest.status==='draft')return ['审核最新报价',`第 ${latest.version} 版仍为草稿，请补全信息并核对金额与条款。`,'quote-review',latest.id];
  if(!latest.sent_at)return ['确认报价发送情况',`第 ${latest.version} 版已审核。自行发送后，请手动标记已发送。`,'quote-send',latest.id];
  if(i.next_followup&&i.next_followup<=state.data.today)return ['完成到期跟进',`计划跟进：${i.next_followup}`,'followups'];
  return ['记录下一步跟进','报价已标记发送，安排下一次联系。','followups'];
}
function renderDashboard(){
  const d=state.data,products=activeProducts(),active=d.inquiries.filter(i=>!['成交','关闭'].includes(i.status));const pending=active.filter(i=>!i.analysis_reviewed),drafts=d.inquiries.map(i=>latestQuote(i.id)).filter(q=>q?.status==='draft'),due=active.filter(i=>i.next_followup&&i.next_followup<=d.today),complete=products.filter(p=>!p.missing?.length);
  const ordered=[...active].sort((a,b)=>(a.next_followup||'9999').localeCompare(b.next_followup||'9999'));
  const logged=d.inquiries.filter(i=>i.baseline_minutes!==null&&i.baseline_minutes!==undefined&&i.baseline_minutes!==''&&i.actual_minutes!==null&&i.actual_minutes!==undefined&&i.actual_minutes!==''&&state.workspace==='live'&&d.activities.some(a=>a.inquiry_id===i.id&&a.kind==='ai_success'&&a.mode==='live'));
  const delta=logged.reduce((sum,i)=>sum+Number(i.baseline_minutes)-Number(i.actual_minutes),0);
  return pageHead('YOUR DAILY WORKSPACE','把今天的询盘，向前推进一步。','产品、询盘、报价与跟进集中在这里。每一步都有依据，每一份报价由您确认。',btn('录入新询盘','new-inquiry','primary','','plus'))+
  `<div class="metric-grid">${[['待审核询盘',pending.length,'需求与选型等待您的确认','inbox','accent'],['待审核报价',drafts.length,'仅统计各询盘最新版本的待审核草稿','file',''],['到期跟进',due.length,'今天及已逾期的联系计划','clock',''],['产品资料',products.length,`${complete.length} 项基本资料完整 · ${products.length-complete.length} 项待补充`,'box','']].map(([l,n,f,ico,c])=>`<div class="metric ${c}"><div class="metric-label">${l}${icon(ico)}</div><div class="metric-number">${n.toString().padStart(2,'0')}</div><div class="metric-foot">${f}</div></div>`).join('')}</div>
  <div class="columns"><div><section class="card"><div class="card-head"><div><h2>接下来需要处理<span class="count-tag">${active.length}</span></h2><p>按跟进日期排序，继续尚未完成的业务。</p></div><span class="dashboard-date">${e(d.today)}</span></div>${ordered.length?ordered.slice(0,8).map(i=>{const [label,desc,tab,quoteId]=nextAction(i);return `<div class="task-row"><div class="task-icon">${icon(tab.startsWith('quote')?'file':tab==='followups'?'clock':'inbox')}</div><div class="task-text"><div class="task-title">${e(i.title||'未命名询盘')} ${statusPill(i.status)}</div><div class="task-sub">${e(customer(i.customer_id).name)} · ${e(desc)}</div></div>${btn(label,quoteId?'open-quote':'open-inquiry','small',`data-id="${quoteId||i.id}" data-tab="${tab}"`,'arrow')}</div>`}).join(''):empty('从第一份产品资料开始','准备好基础资料后，就可以录入客户英文询盘。','new-product','录入产品','box')}</section>
  <section class="card"><div class="card-head"><div><h2>最近业务记录</h2><p>记录真实处理过程，方便回看。</p></div></div><div class="card-body">${d.activities.length?[...d.activities].sort((a,b)=>b.id-a.id).slice(0,5).map(a=>`<div class="activity-row"><span class="activity-dot"></span><div class="activity-content"><strong>${e(a.message||activityLabel(a.kind))}</strong>${a.mode==='demo'?` ${pill('演示','amber')}`:''}${a.duration_ms!==undefined?` <span class="muted">${(a.duration_ms/1000).toFixed(2)} 秒</span>`:''}<time>${timeText(a.created_at)}</time></div></div>`).join(''):'<div class="muted small-text">暂无记录。导入、分析、审核和跟进将逐步留下业务轨迹。</div>'}</div></section></div>
  <div><section class="card"><div class="card-head"><h2>一条完整的业务流程</h2><span class="tiny muted">从资料到跟进</span></div><div class="card-body"><div class="workflow-list">${[['准备产品资料','保留原始型号、单位和资料来源',products.length>0],['整理客户询盘','区分原文、推测与缺失信息',d.inquiries.some(i=>i.analysis)],['人工确认选型','先核对硬性参数，再确认候选',d.inquiries.some(i=>i.analysis_reviewed)],['审核英文报价','确认售价、币种、交期及条款',d.quotes.some(q=>q.status==='approved')],['记录发送与跟进','手动发送，留下下一次联系日期',d.inquiries.some(i=>i.followups?.length)]].map(([a,b,done],idx)=>`<div class="workflow-item"><span class="step-num ${done?'done':''}">${done?'✓':idx+1}</span><div class="step-text"><strong>${a}</strong><p>${b}</p></div></div>`).join('')}</div><div class="hint-block">${d.ai.configured?'模型已配置。首次使用请先实测一封不含敏感资料的询盘。':'AI 尚未接入。您仍可手动填写需求、确认选型并完成报价。'}<br><a href="#settings">查看配置与备份 ${icon('arrow')}</a></div></div></section>
  <section class="card card-pad"><div class="split-heading"><h3>有记录，才计算效率</h3>${icon('clock')}</div><p class="muted small-text">${logged.length?`已记录 ${logged.length} 封真实模型询盘的人工基准和实际处理时间。合计${delta>=0?'减少':'增加'} ${Math.abs(delta).toFixed(1)} 分钟。`:'尚无同时包含人工基准、实际耗时及真实模型处理的记录，暂不计算节省时间。'}</p><div class="help-line">${icon('check')}演示处理不计入真实效率</div></section></div></div>`;
}
function activityLabel(k){return ({ai_success:'AI 分析完成',ai_failure:'AI 处理失败',human_edit:'人工修改',quote_created:'保存报价版本',quote_approved:'审核报价',quote_sent:'更新发送标记',followup:'记录跟进'})[k]||'业务资料更新';}
function specsText(p){return Object.entries(p.specs||{}).filter(([,v])=>v!==''&&v!==null).map(([k,v])=>`${fieldNames[k]||k}: ${v}`).join(' · ');}
function productSpecs(p){
  const main=['source_specification','poles','current_a','voltage_v','curve','breaking_ka','review_notes'];
  const labels={source_specification:'资料摘要 / 原规格',review_notes:'待确认',source_pages:'目录页码',catalog_scope:'参数适用范围',related_families:'关联大类'};
  const entries=Object.entries(p.specs||{}).filter(([k,v])=>v!==''&&v!==null&&!['product_family','record_type'].includes(k));
  const line=([k,v])=>`<div class="product-spec-line ${k==='review_notes'?'product-review-note':''}"><span>${e(labels[k]||fieldNames[k]||k)}：</span>${e(v)}</div>`;
  const primary=main.flatMap(key=>entries.filter(([k])=>k===key));
  const other=entries.filter(([k])=>!main.includes(k));
  return `<div class="product-specs">${primary.length?primary.map(line).join(''):(!other.length?'<span class="muted">关键参数待补充</span>':'')}${other.length?`<details class="product-extra-specs"><summary>其他资料 · ${other.length} 项</summary>${other.map(line).join('')}</details>`:''}</div>`;
}
function renderProducts(){
  const all=state.data.products, archived=all.filter(p=>p.archived).length;
  const base=state.showArchivedProducts?all:activeProducts(), ps=base.filter(p=>productMatchesFilters(p,false));
  const familyOptions=[...productFamilies,...new Set(base.map(productFamily).filter(f=>!productFamilies.includes(f)))];
  const categories=[...new Set(base.filter(p=>!state.productFamily||productFamily(p)===state.productFamily).map(p=>p.category).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN'));
  const familyCards=[['','全部产品'],...familyOptions.map(f=>[f,f])].map(([v,label])=>{const rows=activeProducts().filter(p=>!v||productFamily(p)===v),unpriced=rows.filter(p=>p.purchase_price===''||p.purchase_price==null).length;return `<button type="button" class="catalog-family ${state.productFamily===v?'selected':''}" data-action="product-family" data-family="${e(v)}" aria-pressed="${state.productFamily===v}"><span>${e(label)}</span><strong>${rows.length}</strong><small>${unpriced} 条价格待录入</small></button>`;}).join('');
  return pageHead('PRODUCT LIBRARY','按产品大类，管理供货资料。','目录系列与带报价的具体规格分别保存。未提供的价格保持空白，可随时编辑补充；系列参数范围不代表每个配置都具备。',btn('导入 Excel / CSV','import-products','','','upload')+btn('手动录入产品','new-product','primary','','plus'))+
  `<div class="catalog-families" aria-label="产品大类">${familyCards}</div><section class="card"><div class="table-tools product-table-tools"><input class="search" type="search" id="product-search" aria-label="搜索产品" value="${e(state.productSearch)}" placeholder="搜索型号、名称、规格或来源…"><span id="product-filter-count" class="small-text muted">显示 ${ps.filter(p=>productMatchesFilters(p)).length} 条 · ${activeProducts().length} 条在用 · ${archived} 条归档</span><label class="inline-check product-archive-toggle"><input type="checkbox" id="show-archived-products" ${state.showArchivedProducts?'checked':''}>显示已归档产品</label></div><div class="catalog-filters">${selectField('子分类','product-category-filter',state.productCategory,[{value:'',label:'全部子分类'},...categories.map(c=>({value:c,label:productCategoryLabel(c)}))])}${selectField('价格状态','product-price-filter',state.productPrice,[{value:'',label:'全部价格状态'},{value:'missing',label:'价格待录入'},{value:'priced',label:'已录入价格'}])}${selectField('资料类型','product-kind-filter',state.productKind,[{value:'',label:'全部资料类型'},{value:'series',label:'目录系列（具体配置待选）'},{value:'variant',label:'具体产品 / 报价规格'}])}<div class="actions"><a class="btn small" href="${apiUrl('/api/templates/products.xlsx')}">${icon('download')}Excel 模板</a><a class="btn small" href="${apiUrl('/api/templates/products.csv')}">CSV 模板</a></div></div>${ps.length?`<div class="table-wrap"><table class="product-library-table"><thead><tr><th>产品 / 原始型号</th><th>主要规格与来源</th><th>供应商</th><th>采购成本</th><th>起订量 / 交期</th><th>资料状态</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr data-product-search="${e(productSearchText(p))}" ${productMatchesFilters(p)?'':'hidden'}><td><span class="sub catalog-category">${e(productFamily(p))} / ${e(productCategoryLabel(p.category))}</span><strong class="mono">${e(p.model||'型号待补充')}</strong><span class="sub">${e(p.name||'名称待补充')}</span><span class="sub">${e(p.name_en)}</span>${pill(productKindLabel(p),productIsSeries(p)?'blue':'gray')}${p.archived?pill('已归档 · 只读','gray'):''}</td><td>${productSpecs(p)}<span class="sub product-source">来源：${e(p.source||'未录入')}</span></td><td>${e(p.supplier||'待补充')}</td><td class="nowrap">${p.purchase_price===''||p.purchase_price==null?pill('价格待录入','amber'):money(p.purchase_price,p.currency)}<span class="sub">/ ${e(p.unit||'单位待确认')}</span></td><td>${e(p.moq||'待确认')} ${e(p.unit)}<span class="sub">${e(p.lead_time||'交期待确认')}</span></td><td>${p.missing?.length?pill(`缺 ${p.missing.length} 项`,'amber'):pill('资料完整','green')}<span class="sub">资料 ${e(dateText(p.source_updated_at))}</span>${p.archived?`<span class="sub">归档 ${e(dateText(p.archived_at))}</span>`:''}</td><td>${p.archived?'<span class="small-text muted">仅供历史查阅</span>':btn('编辑','edit-product','small',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state compact">当前分类或筛选条件下没有产品。可切换大类或清除筛选。</div>'}</section>
  <div class="banner info">${icon('check')}<div>采购价和供应商信息仅用于内部成本分析。客户英文报价单不包含这些字段。更新或归档产品资料不会更改历史报价；已归档产品不再参与新业务选型。</div></div>`;
}
function productModal(id){const p=id?product(id):{};if(p.archived){toast('已归档产品仅供历史查阅，暂不支持编辑或恢复。',true);return;}const sp=p.specs||{};modal(id?'编辑产品资料':'录入产品资料','缺少资料可以先保存，系统会标出缺失项。型号与单位请按来源原样填写。',`<form id="product-form" data-id="${id||''}"><div class="error-box"></div><div class="form-grid">${field('供应商','supplier',p.supplier)}${field('产品名称（中文）','name',p.name)}${field('产品名称（英文，用于报价）','name_en',p.name_en)}${field('型号 / 系列（保留原文）','model',p.model)}${selectField('产品大类','product_family',sp.product_family||'',[{value:'',label:'未分类'},...productFamilies,...(sp.product_family&&!productFamilies.includes(sp.product_family)?[sp.product_family]:[])])}${field('子分类','category',p.category||'',{help:'例如 MCB、交流充电桩、真空断路器、配电变压器；按原资料填写。'})}${selectField('资料类型','record_type',sp.record_type||'product_variant',[{value:'product_variant',label:'具体产品规格'},{value:'quote_variant',label:'报价规格'},{value:'catalog_series',label:'目录系列（具体配置待选）'}])}${field('计量单位（保留原文）','unit',p.unit,{placeholder:'例如：pcs；不得擅自换算为箱'})}</div><div class="section-title">目录摘要与待确认事项</div><div class="form-grid">${field('原规格 / 目录摘要','source_specification',sp.source_specification,{area:true,rows:3,full:true})}${field('待确认事项','review_notes',sp.review_notes,{area:true,rows:3,full:true})}</div><div class="section-title">通用电气参数（仅填写资料明确的值）</div><div class="form-grid three">${field('极数','poles',sp.poles,{placeholder:'例如：2P'})}${field('额定电流 (A)','current_a',sp.current_a)}${field('额定电压 (V)','voltage_v',sp.voltage_v)}${field('脱扣曲线','curve',sp.curve,{placeholder:'例如：C'})}${field('分断能力 (kA)','breaking_ka',sp.breaking_ka)}${field('其他规格（JSON 对象）','extra_specs',JSON.stringify(Object.fromEntries(Object.entries(sp).filter(([k])=>!['poles','current_a','voltage_v','curve','breaking_ka','product_family','record_type','source_specification','review_notes'].includes(k)))) ,{area:true,rows:5,full:true,help:'完整保留来源扩展字段；只修改已核实内容。可选，例如 {"frequency_hz":"50/60"}'})}</div><div class="section-title">成本与供货资料 · 仅内部可见</div><div class="form-grid">${field('采购单价','purchase_price',p.purchase_price,{type:'number',step:'any',min:0})}${selectField('采购币种','currency',p.currency||'', [{value:'',label:'请选择币种'},...currencies])}${field('最小起订量','moq',p.moq,{type:'number',step:'any',min:0})}${field('供应商交期（原文）','lead_time',p.lead_time)}${field('资料来源','source',p.source,{placeholder:'供应商报价单名称、日期或产品手册页码'})}${field('资料更新时间','source_updated_at',p.source_updated_at,{type:'date',help:'填写供应商资料日期；不填写则标为待补充。'})}</div>${p.missing?.length?`<div class="banner space-top">${icon('alert')}当前缺失：${e(p.missing.join('、'))}</div>`:''}${formActions('保存产品资料')}</form>`,true);}
function importModal(){state.importData=null;modal('批量导入产品资料','先下载模板，填入真实来源资料。导入前逐行检查错误与缺失项。',`<div class="actions"><a class="btn small" href="${apiUrl('/api/templates/products.xlsx')}">${icon('download')}空白 Excel 模板</a><a class="btn small" href="${apiUrl('/api/templates/products.csv')}">空白 CSV 模板</a><a class="btn small" href="${apiUrl('/api/templates/example.xlsx')}">虚构示例文件</a></div><form id="import-preview-form" class="space-top"><div class="error-box"></div><div class="import-drop"><label for="import-file">选择 .xlsx 或 .csv 文件（最大 5 MB）</label><br><input type="file" id="import-file" name="file" accept=".csv,.xlsx" required><p class="muted small-text">保留文件中的型号、单位和币种；不会自动替换或补全产品参数。</p><button type="submit" class="btn primary">读取并预览</button></div></form><div id="import-results"></div>`,true);}
function importResults(data){
  const errors=data.errors||[], rows=data.rows||[], bad=errors.length||rows.some(r=>r.errors?.length);
  state.importData=data;
  $('#import-results').innerHTML=`<div class="section-heading"><h3>导入预览 · ${rows.length} 行</h3>${bad?pill('存在错误，请修改原文件','red'):pill('可导入','green')}</div>${errors.length?`<div class="error-box">${errors.map(e).join('<br>')}</div>`:''}<input type="search" id="import-row-search" class="search" aria-label="搜索导入预览" placeholder="搜索预览中的型号、名称、分类或原规格…"><p class="field-help">核对原始型号、分类、价格、规格及来源。下方表格可横向、纵向滚动，原始单价不做四舍五入。</p><div class="table-wrap import-preview-scroll" tabindex="0" aria-label="产品导入预览表，可滚动"><table class="import-preview-table"><thead><tr><th>文件行</th><th>产品 / 型号 / 分类</th><th>单位 / 采购成本</th><th>规格参数</th><th>来源 / 日期</th><th>检查结果</th></tr></thead><tbody>${rows.map(r=>{const p=r.product||{};return `<tr data-import-search="${e([p.model,p.name,p.category,p.supplier,specsText(p)].join(' ').toLowerCase())}"><td>${e(r.row)}</td><td><strong class="mono">${e(p.model)}</strong><span class="sub">${e(p.name)} / ${e(p.supplier)}</span><span class="sub">分类：${e(p.category||'待补充')}</span></td><td class="nowrap">${e(p.unit||'单位待补充')}<span class="sub mono">${money(p.purchase_price,p.currency)}</span></td><td>${productSpecs(p)}</td><td class="product-source">${e(p.source||'来源待补充')}<span class="sub">资料日期：${e(dateText(p.source_updated_at||p.updated_at))}</span></td><td>${r.errors?.length?r.errors.map(t=>`<div class="red-text">${e(t)}</div>`).join(''):pill('校验通过','green')}${(r.warnings||[]).map(t=>`<div class="small-text muted">${e(t)}</div>`).join('')}</td></tr>`;}).join('')}</tbody></table></div><div class="form-note">${state.workspace==='demo'?'即将导入示例 / 测试空间。导入资料按实际来源记录，测试报价仍带示例标记。':'即将导入正式资料空间。请勿将虚构示例当作真实商品资料。'} 默认新增记录，不覆盖同型号的已有记录。</div>${state.workspace==='demo'?'<div class="inline-check space-top"><input id="import-replace-demo" type="checkbox"><label for="import-replace-demo">替换预置示例产品（自动备份并归档，保留报价历史）<span class="field-help">仅归档系统预置的虚构 DEMO 型号；已导入的真实资料和历史业务记录继续保留。</span></label></div>':''}<div class="form-actions">${btn('关闭','close-modal')}${btn(`确认导入 ${rows.length} 行`,'commit-import','primary',bad||!rows.length?'disabled':'')}</div>`;
}

function renderInquiries(){const ins=[...state.data.inquiries].sort((a,b)=>b.id-a.id);let selected=inquiry(state.inquiryId);if(!selected&&ins.length){selected=ins[0];state.inquiryId=selected.id;}return pageHead('INQUIRIES & RELATIONSHIPS','把客户的原话，变成明确的下一步。','保存英文原文，核对需求依据，再由您确认产品。英文邮件保持为草稿，由您自行发送。',btn('客户资料','manage-customers','','','users')+btn('新建询盘','new-inquiry','primary','','plus'))+
  `<div class="inquiry-layout"><section class="card inquiry-list"><div class="card-head"><h2>全部询盘<span class="count-tag">${ins.length}</span></h2></div>${ins.length?ins.map(i=>`<div class="inquiry-row ${selected?.id===i.id?'active':''}" data-action="open-inquiry" data-id="${i.id}" tabindex="0" role="button" aria-label="打开${e(i.title)}"><h3>${e(i.title||'未命名询盘')}</h3><div>${statusPill(i.status)} ${i.analysis_reviewed?pill('已审核','green'):''}</div><p>${e(customer(i.customer_id).name)} · ${e(customer(i.customer_id).country||'地区待补充')}</p><p>跟进：${e(dateText(i.next_followup))}</p></div>`).join(''):'<div class="empty-state compact">暂无询盘</div>'}</section><section class="card inquiry-detail">${selected?renderInquiryDetail(selected):empty('录入第一封客户询盘','先建立客户，再粘贴英文邮件或询盘原文。','new-inquiry','新建询盘')}</section></div>`;}
function renderInquiryDetail(i){const c=customer(i.customer_id);return `<div class="card-head"><div><h2>${e(i.title||'未命名询盘')}</h2><div class="inquiry-meta"><span>${e(c.name)}</span><span>${e(c.country||'国家/地区待补充')}</span><span>${e(c.contact)}</span></div></div>${btn('编辑原文','edit-inquiry','small',`data-id="${i.id}"`,'edit')}</div><div class="tabs" role="tablist">${[['analysis','01 需求整理'],['matching','02 选型审核'],['followups','03 报价与跟进']].map(([t,l])=>`<button role="tab" aria-selected="${state.tab===t}" class="tab ${state.tab===t?'active':''}" data-action="inquiry-tab" data-tab="${t}">${l}</button>`).join('')}</div><div class="card-body">${state.tab==='analysis'?analysisPane(i):state.tab==='matching'?matchingPane(i):followupPane(i)}</div>`;}
function analysisRows(reqs){return reqs.map((r,idx)=>`<tr class="requirement-row"><td class="analysis-field"><select name="req_field" aria-label="第 ${idx+1} 行需求字段">${Object.entries(fieldNames).map(([v,l])=>`<option value="${v}" ${r.field===v?'selected':''}>${l}</option>`).join('')}${!fieldNames[r.field]?`<option value="${e(r.field)}" selected>${e(r.field)}</option>`:''}</select></td><td class="analysis-value"><input name="req_value" aria-label="第 ${idx+1} 行提取值" value="${e(r.value)}" placeholder="未知则留空"></td><td class="analysis-kind"><select name="req_kind" aria-label="第 ${idx+1} 行依据类型"><option value="stated" ${r.kind==='stated'?'selected':''}>原文已说明</option><option value="inferred" ${r.kind==='inferred'?'selected':''}>推测 / 待确认</option><option value="missing" ${r.kind==='missing'?'selected':''}>信息缺失</option></select></td><td><textarea name="req_evidence" aria-label="第 ${idx+1} 行原文依据" rows="2" placeholder="粘贴对应的原文片段">${e(r.evidence)}</textarea></td><td>${btn('×','remove-requirement','small','aria-label="移除此条需求"')}</td></tr>`).join('');}
function analysisPane(i){const a=i.analysis||{requirements:Object.keys(fieldNames).map(field=>({field,value:'',kind:'missing',evidence:''})),questions:[],warnings:[],mode:'manual'};return `<div class="split-heading"><h3>客户询盘原文</h3>${statusPill(i.status)}</div><pre class="original-text">${e(i.original_text)}</pre><div class="analysis-toolbar">${btn(i.analysis?'重新调用真实 AI':'AI 提取需求','analyze-live','primary',`data-id="${i.id}" ${state.data.ai.configured?'':'disabled'}`,'spark')}${state.workspace==='demo'?btn('演示提取（非真实模型）','analyze-demo','',`data-id="${i.id}"`):''}${!state.data.ai.configured?'<a class="small-text" href="#settings">AI 未接入 · 查看本地配置</a>':''}</div><div id="analysis-error" class="error-box"></div>
  ${a.mode==='demo'?`<div class="banner">${icon('alert')}以下为演示规则提取，不属于真实模型接入验收。</div>`:''}${a.warnings?.length?`<div class="banner">${icon('alert')}<div>${a.warnings.map(e).join('<br>')}</div></div>`:''}
  <form id="analysis-form" data-id="${i.id}"><div class="error-box"></div><div class="section-heading"><h3>需求与原文依据</h3>${i.analysis_reviewed?pill('已人工审核','green'):pill('待人工核对','amber')}</div><p class="evidence-note">可直接手工录入。“原文已说明”必须包含准确原文片段；补充或推测信息请标为“推测 / 待确认”。缺失值不参与匹配。</p><div class="table-wrap"><table class="analysis-table"><thead><tr><th>需求字段</th><th>需求值</th><th>依据类型</th><th>对应原文（可编辑）</th><th></th></tr></thead><tbody id="requirements-body">${analysisRows(a.requirements)}</tbody></table></div>${btn('增加需求字段','add-requirement','ghost small','','plus')}
  <div class="section-heading"><h3>进一步确认的问题</h3></div>${field('每行一个问题','questions',(a.questions||[]).join('\n'),{area:true,rows:3,full:true,placeholder:'请根据缺失信息补充要向客户确认的问题。'})}<div class="section-heading"><h3>英文回复草稿</h3>${pill('由您自行发送','gray')}</div>${field('回复内容（可直接编辑）','reply_draft',i.reply_draft||a.reply_draft,{area:true,rows:7,full:true,placeholder:'AI 接入后可生成草稿，也可以手动填写。'})}<div class="form-actions">${btn('仅保存回复草稿','save-reply','',`data-id="${i.id}"`)}<button class="btn primary" type="submit">保存分析，检查候选 ${icon('arrow')}</button></div></form>`;}
async function loadMatches(id){try{state.matches[id]=await api(`/api/inquiries/${id}/matches`);}catch(err){state.matches[id]={candidates:[],message:err.message};}}
function matchingPane(i){if(!i.analysis)return `<div class="banner info">${icon('alert')}尚未整理需求。请先提取询盘，或手动填写有依据的需求。</div>${btn('返回需求整理','inquiry-tab','primary','data-tab="analysis"')}`;
  const result=state.matches[i.id];const candidates=result?.candidates||[];return `<div class="split-heading"><h3>候选产品与逐项检查</h3>${btn('重新检查','refresh-matches','small',`data-id="${i.id}"`)}</div><div class="banner info">${icon('check')}有依据且无参数冲突的产品才进入候选。存在硬性冲突的产品无法确认；待确认项需要您记录核实依据。</div><p class="muted small-text">${e(result?.message||'正在读取候选结果…')}</p><form id="review-form" data-id="${i.id}"><div class="error-box"></div>${candidates.length?candidates.map(m=>{const p=product(m.product_id);return `<div class="matching-card ${m.status}"><div class="match-top"><input type="checkbox" name="selected_product_ids" value="${p.id}" id="select-product-${p.id}" ${i.selected_product_ids?.includes(p.id)?'checked':''} ${m.status==='conflict'?'disabled':''}><label for="select-product-${p.id}"><span class="match-model"><strong class="mono">${e(p.model||'型号缺失')}</strong>${pill(m.status==='eligible'?'参数符合 · 待人工确认':m.status==='conflict'?'参数冲突 · 不可选':'存在待确认项',m.status==='eligible'?'green':m.status==='conflict'?'red':'amber')}</span><span class="match-name">${e(p.name)} · ${e(p.supplier)} · ${e(p.unit||'单位待补充')}</span></label></div><div class="match-details">${(m.reasons||[]).map(t=>`<p class="reason-text">✓ ${e(t)}</p>`).join('')}${(m.conflicts||[]).map(t=>`<p class="conflict-text">× ${e(t)}</p>`).join('')}${(m.pending||[]).map(t=>`<p class="pending-text">? ${e(t)}</p>`).join('')}</div></div>`}).join(''):empty('暂无可检查的候选产品','请先录入产品，或补充已核实的需求参数。','','','box')}
  <div class="section-title">您的审核记录</div>${field('选型说明 / 待确认项核实依据','selection_note',i.selection_note,{area:true,rows:3,full:true,placeholder:'例如：已与客户确认包装单位为 pcs；如尚未确认，请先向客户补充询问。',help:'待确认候选被选中时必须填写。参数冲突不会因为填写说明而解除。'})}<div class="form-grid space-top">${field('原来手工处理所需时间（分钟）','baseline_minutes',i.baseline_minutes,{type:'number',min:0,step:'any',help:'按实际经验填写；没有基准可以留空。'})}${field('本次人工处理实际耗时（分钟）','actual_minutes',i.actual_minutes,{type:'number',min:0,step:'any',help:'记录您实际花费的处理时间，未记录不计算效率。'})}</div><div class="form-actions">${btn('返回修改需求','inquiry-tab','','data-tab="analysis"')}<button type="submit" class="btn primary">确认需求与选型 ${icon('check')}</button></div></form>${i.analysis_reviewed&&i.selected_product_ids?.length?`<div class="next-step"><p>已确认 ${i.selected_product_ids.length} 个型号，可以开始填写报价。</p>${btn('创建报价草稿','new-quote','primary',`data-id="${i.id}"`,'arrow')}</div>`:''}`;}
function followupPane(i){const qs=state.data.quotes.filter(q=>q.inquiry_id===i.id).sort((a,b)=>b.version-a.version);return `<div class="split-heading"><h3>这份询盘的报价</h3>${btn('创建报价','new-quote','small primary',`data-id="${i.id}" ${i.analysis_reviewed&&i.selected_product_ids?.length?'':'disabled'}`,'plus')}</div>${!i.analysis_reviewed?`<div class="banner">${icon('alert')}请先完成需求与选型审核，再创建可正式审核的报价。</div>`:''}${qs.length?`<div class="table-wrap"><table><thead><tr><th>报价 / 版本</th><th>总额</th><th>审核与发送</th><th></th></tr></thead><tbody>${qs.map(q=>`<tr><td>${e(q.number)} / V${q.version}</td><td>${money(q.snapshot.total,q.snapshot.currency)}</td><td>${pill(q.status==='approved'?'已审核':'草稿',q.status==='approved'?'green':'amber')} ${q.sent_at?pill('已手动标记发送','blue'):''}</td><td>${btn('查看','open-quote','small',`data-id="${q.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="small-text muted">尚未保存报价版本。</p>'}<div class="section-title">记录跟进与下一步</div><form id="followup-form" data-id="${i.id}"><div class="error-box"></div><div class="form-grid">${selectField('处理状态','status',i.status,statuses)}${field('下一次跟进日期','next_followup',i.next_followup,{type:'date'})}${field('本次跟进记录','note','',{area:true,rows:3,full:true,required:true,placeholder:'记录客户反馈、待办事项或人工发送的邮件内容。'})}${field('成交 / 关闭原因','reason',i.reason,{full:true,placeholder:'状态为成交或关闭时必填'})}</div><div class="form-actions"><button type="submit" class="btn primary">保存跟进记录</button></div></form>${i.followups?.length?`<div class="section-title">跟进历史</div><div class="timeline">${[...i.followups].reverse().map(f=>`<div class="timeline-item"><time>${timeText(f.created_at)} · ${e(f.status)} · 下次：${e(dateText(f.next_followup))}</time><p>${e(f.note)}</p>${f.reason?`<p class="small-text muted">原因：${e(f.reason)}</p>`:''}</div>`).join('')}</div>`:''}`;}
function customerModal(id,after=''){const c=id?customer(id):{};modal(id?'编辑客户资料':'新建客户','客户联系方式仅保存在本地，不会自动同步邮箱或向客户发送消息。',`<form id="customer-form" data-id="${id||''}" data-after="${after}"><div class="error-box"></div><div class="form-grid">${field('客户 / 公司名称','name',c.name,{required:true})}${field('国家或地区','country',c.country)}${field('联系方式','contact',c.contact,{placeholder:'邮箱、电话或其他联系方式'})}${field('客户来源','source',c.source,{placeholder:'展会、平台、自主来信等'})}${field('备注','notes',c.notes,{area:true,full:true})}</div>${formActions('保存客户')}</form>`);}
function customersModal(){modal('客户资料','管理真实客户和关联信息。正式资料与虚构示例分开保存。',`${btn('新建客户','new-customer','primary','','plus')}<div class="table-wrap space-top"><table><thead><tr><th>客户</th><th>地区 / 联系方式</th><th>来源</th><th></th></tr></thead><tbody>${state.data.customers.map(c=>`<tr><td><strong>${e(c.name)}</strong><span class="sub">${e(c.notes)}</span></td><td>${e(c.country)}<span class="sub">${e(c.contact)}</span></td><td>${e(c.source)}</td><td>${btn('编辑','edit-customer','small',`data-id="${c.id}"`)}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">暂无客户资料</td></tr>'}</tbody></table></div>`,true);}
function inquiryModal(id,newCustomerId){if(!id&&!state.data.customers.length){customerModal(null,'new-inquiry');return;}const i=id?inquiry(id):(state.inquiryDraft||{});modal(id?'编辑询盘原文':'录入客户询盘',id?'修改原文后，旧的需求分析与选型审核会失效，需要重新整理。':'保留原始邮件全文，AI 仅处理本次询盘文本。',`<form id="inquiry-form" data-id="${id||''}"><div class="error-box"></div><div class="form-grid">${id?field('关联客户','customer_display',customer(i.customer_id).name,{readonly:true}):selectField('关联客户','customer_id',newCustomerId||state.data.customers[0]?.id,state.data.customers.map(c=>({value:c.id,label:c.name})))}${field('询盘标题','title',i.title,{placeholder:'例如：英国客户 2P 微型断路器询盘'})}${field('英文邮件 / 询盘原文','original_text',i.original_text,{area:true,rows:11,full:true,required:true,placeholder:'将客户英文询盘原文粘贴到这里…'})}${field('下一次跟进日期','next_followup',i.next_followup,{type:'date'})}</div>${state.workspace==='demo'&&!id?`<div class="space-top">${btn('填入明确标注的虚构示例','sample-inquiry','small')}</div>`:''}${formActions(id?'保存修改':'保存询盘',!id?btn('另建客户','new-customer-for-inquiry','secondary'):'')}</form>`);}
function readAnalysis(form,i){return {...(i.analysis||{}),requirements:$$('.requirement-row',form).map(row=>({field:$('[name=req_field]',row).value,value:$('[name=req_value]',row).value.trim(),kind:$('[name=req_kind]',row).value,evidence:$('[name=req_evidence]',row).value})),questions:$('[name=questions]',form).value.split('\n').map(x=>x.trim()).filter(Boolean),reply_draft:$('[name=reply_draft]',form).value,warnings:i.analysis?.warnings||[],mode:i.analysis?.mode||'manual'};}

function renderQuotes(){const qs=[...state.data.quotes].sort((a,b)=>b.id-a.id);let q=quote(state.quoteId);if(!q&&qs.length){q=qs[0];state.quoteId=q.id;}return pageHead('QUOTATIONS & HISTORY','让每份报价，都经得起回看。','审核前始终为草稿。每次编辑保存为独立新版本，历史金额、产品资料和条款保持当时的样子。',btn('从询盘创建报价','quote-inquiry-picker','primary','','plus'))+
  `<div class="quote-layout"><section class="card quote-list"><div class="card-head"><h2>报价版本<span class="count-tag">${qs.length}</span></h2></div>${qs.length?qs.map(x=>`<div class="quote-row ${x.id===q?.id?'active':''}" data-action="open-quote" data-id="${x.id}" tabindex="0" role="button" aria-label="查看报价 ${e(x.number)} 第 ${x.version} 版"><div class="inquiry-title"><strong class="mono">${e(x.number)}</strong><span class="tiny muted">V${x.version}</span></div><p>${e(x.snapshot.customer?.name)}</p><div>${pill(x.status==='approved'?'已审核':'草稿',x.status==='approved'?'green':'amber')} ${x.sent_at?pill('已发送','blue'):''}</div><div class="amount mono">${money(x.snapshot.total,x.snapshot.currency)}</div><p>${timeText(x.created_at)}</p></div>`).join(''):'<div class="empty-state compact">暂无报价版本</div>'}</section><section class="card">${q?quoteDetail(q):empty('第一份报价，从确认选型开始','打开客户询盘，核对需求、确认候选产品，然后创建报价。','quote-inquiry-picker','选择询盘','file')}</section></div>`;}
function quoteDetail(q){const s=q.snapshot;return `<div class="card-head"><div><h2>${e(q.number)} <span class="muted">/ V${q.version}</span></h2><p>${e(s.customer?.name)} · 保存于 ${e(timeText(q.created_at))}</p></div>${btn('编辑为新版本','edit-quote','small',`data-id="${q.id}"`,'edit')}</div><div class="card-body"><div class="quote-status-line">${pill(q.status==='approved'?'已审核 · 正式报价':'未审核 · DRAFT',q.status==='approved'?'green':'amber')}${q.sent_at?pill(`人工标记已发送 ${dateText(q.sent_at)}`,'blue'):pill('尚未标记发送','gray')}${state.workspace==='demo'?pill('FICTIONAL SAMPLE','amber'):''}</div>${q.validation_errors?.length?`<div class="banner error">${icon('alert')}<div><strong>以下信息不完整，无法生成正式报价：</strong><br>${q.validation_errors.map(e).join('<br>')}<br>请编辑为新版本并补全。</div></div>`:''}
  <div class="split-heading"><h3>本版报价与成本概览</h3><span class="internal-label">内部可见</span></div><div class="quote-summary"><div><span class="sum-label">报价总额</span><strong class="mono">${money(s.total,s.currency)}</strong></div><div><span class="sum-label">已录入成本口径的预估毛利</span><strong class="mono">${s.estimated_profit===null?'待补成本':money(s.estimated_profit,s.currency)}</strong></div><div><span class="sum-label">预估毛利率</span><strong class="mono">${s.margin_pct===null?'—':e(s.margin_pct)+'%'}</strong></div></div>${s.cost_warnings?.length?`<div class="banner">${icon('alert')}<div><strong>成本尚不完整，不计算毛利：</strong><br>${s.cost_warnings.map(e).join('<br>')}</div></div>`:'<p class="small-text muted">毛利仅覆盖此版本录入的采购成本和其他成本，不代表最终净利润。</p>'}
  <div class="table-wrap"><table><thead><tr><th>型号</th><th>数量 / 单位</th><th>销售单价</th><th>内部采购价</th><th>成本换算方向</th><th>销售小计</th></tr></thead><tbody>${s.lines.map(l=>`<tr><td class="mono">${e(l.model)}</td><td>${e(l.quantity||'待填')} ${e(l.unit)}</td><td>${money(l.unit_price,s.currency)}</td><td>${money(l.purchase_price,l.cost_currency)}</td><td class="small-text">1 ${e(l.cost_currency||'采购币种')} = ${e(l.fx_rate||'?')} ${e(s.currency||'报价币种')}</td><td>${money(l.line_total,s.currency)}</td></tr>`).join('')}</tbody></table></div><div class="quote-meta-grid space-top"><div><span class="muted">交期</span>${e(s.lead_time||'待补充')}</div><div><span class="muted">有效期至</span>${e(s.valid_until||'待补充')}</div><div><span class="muted">付款条件</span>${e(s.payment_terms||'待补充')}</div><div><span class="muted">贸易条款</span>${e(s.trade_terms||'待补充')}</div><div><span class="muted">其他成本（内部）</span>${money(s.other_costs,s.currency)}</div><div><span class="muted">内部备注</span>${e(s.internal_note||'未填写')}</div></div>
  <div class="section-heading"><h3>客户英文报价预览</h3><a class="btn small" href="${apiUrl(`/api/quotes/${q.id}/preview`)}" target="_blank" rel="noopener">${icon('external')}新窗口查看</a></div><p class="small-text muted">以下内容与 PDF 使用同一份客户可见数据，不含供应商、采购价、成本、毛利或内部备注。</p><div class="actions">${q.status==='draft'?btn('审核本版报价','approve-quote','primary',`data-id="${q.id}" ${q.validation_errors?.length?'disabled':''}`,'check'):btn(q.sent_at?'撤销已发送标记':'手动标记已发送','mark-sent','secondary',`data-id="${q.id}" data-sent="${!q.sent_at}"`)}<a class="btn" href="${apiUrl(`/api/quotes/${q.id}/pdf`)}">${icon('download')}导出英文 PDF${q.status==='draft'?'（草稿）':''}</a>${btn('记录跟进','open-inquiry','',`data-id="${q.inquiry_id}" data-tab="followups"`,'arrow')}</div><iframe class="quote-preview" src="${apiUrl(`/api/quotes/${q.id}/preview`)}" title="${e(q.number)} 第 ${q.version} 版英文客户报价预览"></iframe></div>`;}
function quotePicker(){const candidates=state.data.inquiries.filter(i=>i.analysis_reviewed&&activeSelectedProducts(i).length&&(i.selected_product_ids||[]).length===activeSelectedProducts(i).length);modal('选择已审核的询盘','只有人工确认选型后，才能创建可审核的正式报价。',candidates.length?`<div>${candidates.map(i=>`<div class="task-row"><div class="task-text"><div class="task-title">${e(i.title)}</div><div class="task-sub">${e(customer(i.customer_id).name)} · ${i.selected_product_ids.length} 个已确认候选</div></div>${btn('创建报价','new-quote','primary small',`data-id="${i.id}"`)}</div>`).join('')}</div>`:empty('尚无已确认选型的询盘','请先在客户询盘中完成需求与选型审核。','go-inquiries','打开询盘'));}
function quoteLine(line,inq,index){const p=product(line.product_id);return `<tr class="quote-line"><td class="quote-line-model"><select name="product_id" aria-label="第 ${index+1} 行产品">${activeSelectedProducts(inq).map(pid=>{const pr=product(pid);return `<option value="${pid}" ${pid===Number(line.product_id)?'selected':''}>${e(pr.model||'型号待填')}</option>`}).join('')}</select><div class="line-help">采购 ${money(p.purchase_price,p.currency)} / ${e(p.unit)}</div></td><td class="quote-line-description"><input name="description" aria-label="第 ${index+1} 行英文产品描述" value="${e(line.description??p.name_en)}" placeholder="English description"></td><td class="quote-line-numeric"><input name="quantity" type="number" step="any" min="0.00000001" value="${e(line.quantity)}" aria-label="第 ${index+1} 行数量" placeholder="待确认"></td><td class="quote-line-unit"><input name="unit" aria-label="第 ${index+1} 行单位" value="${e(p.unit)}" readonly></td><td class="quote-line-numeric"><input name="unit_price" type="number" step="any" min="0" value="${e(line.unit_price)}" aria-label="第 ${index+1} 行销售单价" placeholder="待填写"></td><td class="quote-line-numeric"><input name="fx_rate" type="number" step="any" min="0.00000001" value="${e(line.fx_rate)}" aria-label="第 ${index+1} 行采购至报价币种汇率" placeholder="待填写"><div class="line-help fx-direction">1 ${e(p.currency||'采购币种')} = ? <span class="quote-currency-label">报价币种</span></div></td><td>${btn('×','remove-quote-line','small','aria-label="移除此报价行"')}</td></tr>`;}
function quoteModal(inquiryId,baseId){const i=inquiry(inquiryId);if(!i){toast('请先选择有效询盘。',true);return;}if(!i.analysis_reviewed||!activeSelectedProducts(i).length||activeSelectedProducts(i).length!==(i.selected_product_ids||[]).length){toast('请先重新审核需求并确认未归档的选型，再创建报价。',true);state.tab='matching';closeModal();navigate('inquiries',i.id);return;}const old=baseId?quote(baseId):null;const s=old?.snapshot||{};const lines=old?s.lines.filter(l=>i.selected_product_ids.includes(l.product_id)):i.selected_product_ids.map(product_id=>({product_id}));state.quoteForm={inquiryId:i.id,baseId};modal(old?`编辑 ${old.number} V${old.version} · 保存为新版本`:'创建英文报价草稿','请逐项确认产品、数量、售价、币种与条款。保存草稿后会计算金额并检查缺失项。',`<form id="quote-form" data-id="${i.id}" data-base="${baseId||''}"><div class="error-box"></div>${old?`<div class="banner info">${icon('file')}旧版保持不变，新版本使用当前产品资料与当前公司资料，保存后需要重新审核。</div>`:''}${!state.data.company.name?`<div class="banner">${icon('alert')}公司英文名称尚未填写。可以先保存草稿，再到设置中补全公司资料并创建新版本。</div>`:''}<div class="form-grid">${field('客户','quote_customer',customer(i.customer_id).name,{readonly:true})}${selectField('本份报价币种','currency',s.currency||'',[{value:'',label:'请选择报价币种'},...currencies],'一份报价仅使用一种币种。')}</div><div class="section-title">报价产品与单价</div><div class="table-wrap"><table class="quote-lines"><thead><tr><th>已确认型号</th><th>英文产品描述</th><th>数量</th><th>原始单位</th><th>销售单价</th><th>采购 → 报价汇率</th><th></th></tr></thead><tbody id="quote-lines-body">${lines.map((l,n)=>quoteLine(l,i,n)).join('')}</tbody></table></div>${btn('增加报价行','add-quote-line','ghost small',`data-id="${i.id}"`,'plus')}<p class="field-help">单位沿用产品资料，不做隐式包装换算。汇率方向为「1 采购币种 = X 报价币种」；同币种自动按 1 计算。销售金额由服务端使用十进制精确计算，保存后显示。</p><div class="section-title">客户可见条款 · 请用英文填写</div><div class="form-grid">${field('交期','lead_time',s.lead_time,{placeholder:'填写已确认的交期，不会自动推测'})}${field('报价有效期至','valid_until',s.valid_until,{type:'date'})}${field('付款条件','payment_terms',s.payment_terms,{placeholder:'填写您确认的付款条件'})}${field('贸易条款（含地点）','trade_terms',s.trade_terms,{placeholder:'例如填写经您确认的条款及指定地点'})}${field('客户可见备注（英文）','customer_note',s.customer_note,{area:true,rows:2,full:true})}</div><div class="section-title">内部成本补充 · 不出现在客户报价单</div><div class="form-grid">${field('其他成本合计（报价币种）','other_costs',s.other_costs,{type:'number',min:0,step:'any',help:'运费、包装、手续费等；未计入请留空，明确没有时填 0。'})}${field('内部备注','internal_note',s.internal_note,{area:true,rows:2})}</div>${state.workspace==='demo'?`<div class="space-top">${btn('填入虚构示例报价条件','sample-quote','small')}</div>`:''}${formActions('保存草稿并预览')}</form>`,true);updateFXLabels();}
function updateFXLabels(){const form=$('#quote-form');if(!form)return;const currency=$('[name=currency]',form).value;$$('.quote-line',form).forEach(row=>{const p=product($('[name=product_id]',row).value);const same=p.currency===currency&&!!currency;const fx=$('[name=fx_rate]',row);if(same)fx.value='1';fx.readOnly=same;$('.fx-direction',row).textContent=`1 ${p.currency||'采购币种'} = X ${currency||'报价币种'}`;});}
function renderSettings(){const d=state.data;return pageHead('LOCAL SETTINGS','一份本地工作空间，长期用下去。','配置报价抬头、查看 AI 接入状态，并定期备份业务资料。API 密钥只从本机环境配置读取。')+`<div class="settings-grid"><section class="card"><div class="card-head"><h2>公司报价抬头</h2>${pill(state.workspace==='demo'?'虚构示例':'正式资料',state.workspace==='demo'?'amber':'green')}</div><div class="card-body"><form id="company-form"><div class="error-box"></div><div class="form-grid">${field('公司英文名称','name',d.company.name,{full:true,required:true,help:'正式报价的必填抬头；请使用真实的英文公司名称。'})}${field('对外联系邮箱','email',d.company.email,{full:true,type:'email'})}${field('英文地址','address',d.company.address,{full:true,area:true,rows:3})}</div><div class="form-actions"><button class="btn primary" type="submit">保存公司资料</button></div></form></div></section>
  <section class="card"><div class="card-head"><h2>AI 模型接入</h2>${pill(d.ai.configured?'已配置 · 以实测为准':'尚未接入',d.ai.configured?'green':'amber')}</div><div class="card-body">${d.ai.error?`<div class="banner error">${icon('alert')}${e(d.ai.error)}</div>`:''}<dl class="config-grid"><dt>服务商</dt><dd>${e(d.ai.provider||'openai')}</dd><dt>模型</dt><dd>${e(d.ai.model||'未配置')}</dd><dt>接口地址</dt><dd>${e(d.ai.base_url||'默认服务商地址')}</dd><dt>超时</dt><dd>${e(d.ai.timeout||'未配置')} 秒</dd></dl><p class="small-text muted">在项目根目录创建本地 .env，参考 .env.example 配置。执行 chmod 600 .env 后刷新页面；每次调用会重新读取配置。密钥不在网页输入，不写入业务备份。</p><pre class="config-code">AI_PROVIDER=openai
AI_MODEL=填写您可用的模型
AI_API_KEY=仅在本机 .env 中填写
AI_TIMEOUT=60
# 兼容服务商可设 AI_PROVIDER=compatible
# 并配置 AI_BASE_URL</pre><p class="small-text muted">真实分析只发送当前询盘原文。按钮“演示提取”不会调用模型；缺少密钥时仍可手动录入和审核。</p></div></section>
  <section class="card full"><div class="card-head"><div><h2>备份与恢复</h2><p>当前空间：${state.workspace==='demo'?'虚构示例':'正式资料'}。两套资料始终分开保存。</p></div><a class="btn primary" href="${apiUrl('/api/backup')}">${icon('download')}下载当前空间备份</a></div><div class="card-body"><div class="form-grid"><div><h3 style="font-size:13px;margin-top:0">建议在重要操作后保存一份备份</h3><p class="small-text muted">备份包含产品、客户、询盘、报价历史、跟进记录和公司抬头。备份中含有业务资料，请放在您信任的位置。API 密钥不包含在备份中。</p><p class="small-text muted">日常关闭网页不会删除资料。完整迁移时，停止应用后也可以备份项目下的 data 文件夹；密钥需单独配置。</p></div><form id="restore-form"><div class="error-box"></div><div class="field"><label for="restore-file">选择本应用导出的 JSON 备份</label><input id="restore-file" type="file" name="file" accept=".json" required><span class="field-help">恢复会替换当前空间的数据。系统先自动保存恢复前备份；仅接受相同数据空间的备份。</span></div><div class="space-top inline-check"><input id="restore-confirm" type="checkbox" required><label for="restore-confirm">我确认恢复到当前${state.workspace==='demo'?'虚构示例':'正式资料'}空间，并替换现有资料。</label></div><div class="form-actions"><button class="btn danger" type="submit">恢复此备份</button></div></form></div></div></section>
  <section class="card full"><div class="card-head"><h2>导入模板与练习资料</h2></div><div class="card-body"><div class="actions"><a class="btn" href="${apiUrl('/api/templates/products.xlsx')}">${icon('download')}正式资料空白 Excel 模板</a><a class="btn" href="${apiUrl('/api/templates/products.csv')}">正式资料空白 CSV 模板</a><a class="btn" href="${apiUrl('/api/templates/example.xlsx')}">虚构示例 Excel</a></div><p class="form-note">从右上角切换到“虚构示例”可以练习完整流程。请核实真实产品参数、供货能力和报价条款后，再填入正式资料。</p></div></section></div>`;}

document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-action]');if(!el||el.disabled)return;
  const action=el.dataset.action,id=Number(el.dataset.id);
  switch(action){
    case 'close-modal':closeModal();break;
    case 'new-product':productModal();break;
    case 'product-family':state.productFamily=el.dataset.family||'';state.productCategory='';render();break;
    case 'edit-product':productModal(id);break;
    case 'import-products':importModal();break;
    case 'commit-import':await work(el,async()=>{const rows=state.importData?.rows?.map(r=>r.product)||[];const result=await api('/api/import/commit',{method:'POST',body:{rows,replace_demo:state.workspace==='demo'&&!!$('#import-replace-demo')?.checked}});await refresh();closeModal();render();toast(`已导入 ${result.count} 条产品资料。${result.archived_count?`已归档 ${result.archived_count} 条预置示例，历史报价保留。`:''}${result.backup_file?'替换前备份已保存。':''}`);});break;
    case 'manage-customers':customersModal();break;
    case 'new-customer':customerModal();break;
    case 'edit-customer':customerModal(id);break;
    case 'new-customer-for-inquiry':state.inquiryDraft=values($('#inquiry-form'));customerModal(null,'new-inquiry');break;
    case 'new-inquiry':state.inquiryDraft=null;inquiryModal();break;
    case 'edit-inquiry':inquiryModal(id);break;
    case 'open-inquiry':state.tab=el.dataset.tab==='quote'?'followups':el.dataset.tab||'analysis';closeModal();navigate('inquiries',id);break;
    case 'go-inquiries':closeModal();navigate('inquiries');break;
    case 'inquiry-tab':state.tab=el.dataset.tab;if(state.tab==='matching'){await loadMatches(state.inquiryId);}render();break;
    case 'analyze-live':case 'analyze-demo':await work(el,async()=>{const mode=action==='analyze-demo'?'demo':'live';$('#analysis-error').textContent='';try{await api(`/api/inquiries/${id}/analyze`,{method:'POST',body:{mode}});}catch(err){const errorBox=$('#analysis-error');if(errorBox)errorBox.textContent=err.message+' 原始询盘和当前编辑内容已保留，可修正配置后重试。';throw err;}await refresh();await loadMatches(id);render();toast(mode==='demo'?'演示提取完成，请逐条核对。此结果不代表真实模型接入。':'真实模型已返回分析，请逐条核对原文依据。');});break;
    case 'add-requirement':$('#requirements-body').insertAdjacentHTML('beforeend',analysisRows([{field:'other',value:'',kind:'missing',evidence:''}]));break;
    case 'remove-requirement':el.closest('tr').remove();break;
    case 'save-reply':await work(el,async()=>{const reply_draft=$('[name=reply_draft]',$('#analysis-form')).value;await api(`/api/inquiries/${id}`,{method:'PUT',body:{reply_draft}});await refresh();toast('英文回复草稿已保存，页面中的需求编辑继续保留。');});break;
    case 'refresh-matches':await work(el,async()=>{await loadMatches(id);render();toast('候选产品检查已更新。');});break;
    case 'new-quote':quoteModal(id);break;
    case 'edit-quote':{const q=quote(id);quoteModal(q.inquiry_id,id);break;}
    case 'quote-inquiry-picker':quotePicker();break;
    case 'open-quote':closeModal();navigate('quotes',id);break;
    case 'approve-quote':await work(el,async()=>{await api(`/api/quotes/${id}/approve`,{method:'POST',body:{}});await refresh();render();toast('本版报价已审核，可以导出正式英文 PDF。');});break;
    case 'mark-sent':await work(el,async()=>{const sent=el.dataset.sent==='true';await api(`/api/quotes/${id}/sent`,{method:'POST',body:{sent}});await refresh();render();toast(sent?'已记录为人工发送。应用没有发送邮件。':'已撤销发送标记。');});break;
    case 'add-quote-line':{const i=inquiry(id);$('#quote-lines-body').insertAdjacentHTML('beforeend',quoteLine({product_id:activeSelectedProducts(i)[0]},i,$$('.quote-line').length));updateFXLabels();break;}
    case 'remove-quote-line':el.closest('tr').remove();break;
    case 'sample-inquiry':{const f=$('#inquiry-form');$('[name=title]',f).value='[虚构示例] 1P 16A 微型断路器询盘';$('[name=original_text]',f).value='Dear Sales Team,\n\nWe are looking for miniature circuit breakers (MCB), 1P, 16A, C curve, rated voltage 230V, breaking capacity 6kA. Quantity: 500 pcs. Please quote in USD and confirm the lead time, payment terms and packing details.\n\nPlease do not offer different current ratings without our approval.\n\nBest regards,\nAlex Morgan\nFictional Northbridge Supply';break;}
    case 'sample-quote':{const f=$('#quote-form');$('[name=currency]',f).value='USD';$('[name=lead_time]',f).value='20 days after order confirmation (fictional example)';const dt=new Date();dt.setDate(dt.getDate()+30);$('[name=valid_until]',f).value=dt.toISOString().slice(0,10);$('[name=payment_terms]',f).value='30% deposit, 70% before shipment (fictional example)';$('[name=trade_terms]',f).value='EXW Ningbo, Incoterms 2020 (fictional example)';$('[name=other_costs]',f).value='0';$('[name=internal_note]',f).value='虚构演示：其他成本暂按 0，本报价不可用于实际交易。';$$('.quote-line',f).forEach(row=>{$('[name=quantity]',row).value='500';$('[name=unit_price]',row).value='3.50';$('[name=fx_rate]',row).value=product($('[name=product_id]',row).value).currency==='CNY'?'0.14':'1';});updateFXLabels();toast('已填入虚构示例条件，请审核每一项。');break;}
  }
});

document.addEventListener('submit',async event=>{
  const form=event.target;if(!(form instanceof HTMLFormElement)||form.hasAttribute('data-v2'))return;event.preventDefault();const button=event.submitter||$('button[type=submit]',form);const id=Number(form.dataset.id);
  await work(button,async()=>{
    $('.error-box',form)?.replaceChildren();
    if(form.id==='product-form'){
      const data=values(form);let extra={};try{extra=JSON.parse(data.extra_specs||'{}');if(!extra||typeof extra!=='object'||Array.isArray(extra))throw new Error();}catch(_){throw new Error('其他规格请填写有效的 JSON 对象，或保留 {}。');}
      data.specs={...extra};for(const k of ['poles','current_a','voltage_v','curve','breaking_ka','product_family','record_type','source_specification','review_notes']){data.specs[k]=data[k];delete data[k];}delete data.extra_specs;
      await api(id?`/api/products/${id}`:'/api/products',{method:id?'PUT':'POST',body:data});await refresh();closeModal();render();toast('产品资料已保存。');
    } else if(form.id==='import-preview-form'){
      const file=$('[name=file]',form).files[0];if(file.size>5*1024*1024)throw new Error('文件超过 5 MB，请拆分后导入。');const result=await api('/api/import/preview',{method:'POST',body:new FormData(form)});importResults(result);
    } else if(form.id==='customer-form'){
      const c=await api(id?`/api/customers/${id}`:'/api/customers',{method:id?'PUT':'POST',body:values(form)});const after=form.dataset.after;await refresh();if(after==='new-inquiry'){inquiryModal(null,c.id);}else{customersModal();}render();toast('客户资料已保存。');
    } else if(form.id==='inquiry-form'){
      const data=values(form);delete data.customer_display;if(data.customer_id)data.customer_id=Number(data.customer_id);const i=await api(id?`/api/inquiries/${id}`:'/api/inquiries',{method:id?'PUT':'POST',body:data});state.inquiryDraft=null;state.inquiryId=i.id;state.tab='analysis';await refresh();closeModal();navigate('inquiries',i.id);toast('询盘原文已保存。');
    } else if(form.id==='analysis-form'){
      const i=inquiry(id),analysis=readAnalysis(form,i);await api(`/api/inquiries/${id}`,{method:'PUT',body:{analysis,reply_draft:analysis.reply_draft}});await refresh();await loadMatches(id);state.tab='matching';render();toast('需求分析已保存，请确认候选产品。');
    } else if(form.id==='review-form'){
      const data=values(form);data.selected_product_ids=$$('[name=selected_product_ids]:checked',form).map(x=>Number(x.value));data.analysis=inquiry(id).analysis;data.reply_draft=inquiry(id).reply_draft;await api(`/api/inquiries/${id}/review`,{method:'POST',body:data});await refresh();await loadMatches(id);render();toast(data.selected_product_ids.length?'人工审核与选型已保存，可以创建报价。':'审核记录已保存，尚未选定报价产品。');
    } else if(form.id==='followup-form'){
      await api(`/api/inquiries/${id}/followups`,{method:'POST',body:values(form)});await refresh();render();toast('跟进记录已保存。');
    } else if(form.id==='quote-form'){
      const data=values(form);delete data.quote_customer;for(const k of ['product_id','description','quantity','unit','unit_price','fx_rate'])delete data[k];data.inquiry_id=id;if(form.dataset.base)data.base_quote_id=Number(form.dataset.base);data.lines=$$('.quote-line',form).map(row=>Object.fromEntries(['product_id','description','quantity','unit','unit_price','fx_rate'].map(k=>[k,k==='product_id'?Number($(`[name=${k}]`,row).value):$(`[name=${k}]`,row).value])));const q=await api('/api/quotes',{method:'POST',body:data});state.quoteId=q.id;await refresh();closeModal();navigate('quotes',q.id);toast(`报价 V${q.version} 草稿已保存，请核对金额与客户预览。`);
    } else if(form.id==='company-form'){
      await api('/api/company',{method:'POST',body:values(form)});await refresh();toast('公司抬头已保存，将用于新建报价版本。');
    } else if(form.id==='restore-form'){
      const result=await api('/api/restore',{method:'POST',body:new FormData(form)});state.inquiryId=null;state.quoteId=null;state.matches={};await refresh();render();toast(result.message||'恢复完成，恢复前资料已自动备份。');
    }
  });
});
document.addEventListener('input',event=>{
  if(event.target.id==='import-row-search'){const q=event.target.value.toLowerCase().trim();$$('[data-import-search]').forEach(row=>row.hidden=!row.dataset.importSearch.includes(q));}
  if(event.target.id==='product-search'){state.productSearch=event.target.value;const q=event.target.value.toLowerCase().trim();const rows=$$('[data-product-search]');rows.forEach(row=>row.hidden=!row.dataset.productSearch.includes(q));const count=$('#product-filter-count');if(count)count.textContent=`显示 ${rows.filter(r=>!r.hidden).length} 条 · ${activeProducts().length} 条在用 · ${(state.data.products||[]).filter(p=>p.archived).length} 条归档`;}
});
document.addEventListener('change',event=>{
  if(event.target.id==='show-archived-products'){state.showArchivedProducts=event.target.checked;render();}
  const catalogFilters={'product-category-filter':'productCategory','product-price-filter':'productPrice','product-kind-filter':'productKind'};
  if(catalogFilters[event.target.id]){state[catalogFilters[event.target.id]]=event.target.value;render();}
  if(event.target.closest('#quote-form')){
    if(event.target.name==='product_id'){const row=event.target.closest('.quote-line'),p=product(event.target.value);$('[name=unit]',row).value=p.unit||'';$('[name=description]',row).value=p.name_en||'';$('[name=fx_rate]',row).value='';$('.line-help',row).textContent=`采购 ${p.currency||''} ${p.purchase_price||'未录入'} / ${p.unit||''}`;}
    if(event.target.name==='currency')$$('.quote-line [name=fx_rate]',$('#quote-form')).forEach(input=>input.value='');
    if(event.target.name==='currency'||event.target.name==='product_id')updateFXLabels();
  }
});
document.addEventListener('keydown',event=>{const target=event.target.closest('[data-action][role=button]');if(target&&(event.key==='Enter'||event.key===' ')){event.preventDefault();target.click();}});
$('#workspace').addEventListener('change',async event=>{const old=state.workspace;state.workspace=event.target.value;state.showArchivedProducts=false;state.productSearch='';state.productFamily='';state.productCategory='';state.productPrice='';state.productKind='';state.inquiryId=null;state.quoteId=null;state.matches={};state.tab='analysis';try{await refresh();localStorage.setItem('trade_workspace',state.workspace);closeModal();if(location.hash.includes('/'))location.hash='#'+state.view;else render();toast(`已切换到${state.workspace==='demo'?'虚构示例':'正式资料'}空间。`);}catch(err){state.workspace=old;$('#workspace').value=old;showError(err);}});
window.addEventListener('hashchange',route);
window.addEventListener('DOMContentLoaded',async()=>{try{await refresh();await route();}catch(err){$('#main').innerHTML=`<div class="empty-state">${icon('alert')}<h3>暂时无法打开工作台</h3><p>${e(err.message)}</p><a class="btn primary" href="/">重新加载</a></div>`;}});
